#!/usr/bin/env python3
# make_bug.py : generate async_fifo_binary_bug.v from rtl/async_fifo.v (the planted CDC bug)
#   the pointers cross the clock domains in BINARY instead of Gray code; full / empty / almost compare in binary
#   run from the repo root:  python3 formal/make_bug.py
src = open("rtl/async_fifo.v").read()
edits = [
    ("`timescale 1ns/1ps\n",
     "`timescale 1ns/1ps\n// async_fifo_binary_bug.v : PLANTED CDC BUG, generated by formal/make_bug.py from rtl/async_fifo.v: the pointers\n"
     "//   cross the clock domains in BINARY instead of Gray code. Passes RTL simulation, fails formal.\n"),
    (".d(rgray), .q(rgray_w2)", ".d(rbin), .q(rgray_w2)"),
    (".d(wgray), .q(wgray_r2)", ".d(wbin), .q(wgray_r2)"),
    ("wfull <= (wgray_next == (rgray_w2 ^ {2'b11, {(AW-1){1'b0}}}));",
     "wfull <= (wbin_next == {~rgray_w2[AW], rgray_w2[AW-1:0]});   // binary: top bit differs, rest equal"),
    ("rempty <= (rgray_next == wgray_r2);", "rempty <= (rbin_next == wgray_r2);   // binary compare"),
    ("wbin_next - g2b(rgray_w2)", "wbin_next - rgray_w2"),
    ("g2b(wgray_r2) - rbin_next", "wgray_r2 - rbin_next"),
]
for old, new in edits:
    assert src.count(old) == 1, f"pattern not found once: {old}"
    src = src.replace(old, new)
open("formal/async_fifo_binary_bug.v", "w").write(src)
print("wrote formal/async_fifo_binary_bug.v")
